CREATE TABLE default.imported_sources_local\n(\n    `create_date_time` DateTime64(3) COMMENT \'Creation date of this row\' CODEC(DoubleDelta, ZSTD(1)),\n    `target_date_time` DateTime COMMENT \'The date of the data that was imported\' CODEC(DoubleDelta, ZSTD(1)),\n    `source` LowCardinality(String) COMMENT \'Source of the data that was imported\'\n)\nENGINE = ReplicatedMergeTree(\'/clickhouse/{installation}/{cluster}/tables/{shard}/default/imported_sources_local\', \'{replica}\')\nPARTITION BY toStartOfMonth(create_date_time)\nORDER BY (create_date_time, source)\nSETTINGS index_granularity = 8192\nCOMMENT 'This table contains the list of sources that have been imported into the database'\n
